import React, { useEffect, useState } from 'react';
import { getNotifications } from '../data/dataFetching';

function Notifications() {

  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    getNotifications().then(data => setNotifications(data));
  }, []);

  let [search, setSearch] = useState("");
  let [sort, setSort] = useState("date");

  function onSearchChange(e) {
    setSearch(e.target.value);
  }

  function onSortChange(e) {
    setSort(e.target.value);
  }
  
  function getSortedNotificationsData() {
    return notifications.filter((item) => {
      return item.message.toLowerCase().includes(search.toLowerCase());
    }).sort((a, b) => {
      return (a[sort] + "").localeCompare(b[sort] + "");
    });
  }

  return (
    <>
    
      <h1>Notifications</h1>

      <div className="tableFunctions">

          {/* Search happens only on message field */}
          <div className="tableSeachbar">
              <i class="bi bi-search"></i>
              <input class="tableSeachInput" type="text" placeholder="Search" onChange={onSearchChange} value={search}></input>
          </div>

          <select className="tableSort" onChange={onSortChange} value={sort}>
              <option selected value="date">
                Date
                <i className='bi bi-chevron-down'></i>
              </option>
              <option value="type">Type</option>
              <option value="message">Message</option>
          </select>

      </div>

      <div className="table-container">
          <table>
              <thead>
                  <tr>
                      <th>Date</th>
                      <th>Type</th>
                      <th>Message</th>
                  </tr>
              </thead>
              <tbody>
                  {getSortedNotificationsData().map((item) => (
                      <tr key={item.id}>
                          <td>{item.date}</td>
                          <td>{item.type}</td>
                          <td>{item.message}</td>
                      </tr>
                  ))}
              </tbody>
          </table>
      </div>

    </>
  )
}

export default Notifications;
